import java.util.Scanner;

public class Main {
    static final long M = 1000000007;
    static long p, k;
    static int[] visited;

    static int visit(int x) {
        int count = 1;
        visited[(int) x] = 1;
        while (visited[(int) ((x * k) % p)] == 0) {
            x = (x * k) % p;
            count++;
            visited[(int) x] = 1;
        }
        return count;
    }

    static long power(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % p;
            }
            base = (base * base) % p;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p = sc.nextLong();
        k = sc.nextLong();
        visited = new int[(int) p];
        long answer = 1;
        for (int i = 1; i < p; ++i) {
            if (visited[i] == 0) {
                int size = visit(i);
                long t = power(k, size);
                if (t != 1 && t != 0)
                    answer = (answer * (size + 1)) % M;
                else
                    answer = (answer * p) % M;
            }
        }
        if (k == 1) {
            answer = (answer * p) % M;
        }
        System.out.println(answer);
        sc.close();
    }
}
